"""Reproduction proof: our generated bytes match the real tx; Ogmios evaluate (gated)."""

import json
import os
from pathlib import Path

import pytest
import requests

from charli3_dendrite.lending.danogo.transactions.context import CreateLoanContext
from charli3_dendrite.lending.danogo.transactions.create_loan import assemble_components

FIX = json.loads(
    (Path(__file__).parent / "fixtures" / "create_loan_tx.json").read_text()
)


def test_generated_bytes_appear_in_real_tx():
    """Offline: the redeemer/datum CBOR we build appears verbatim in the on-chain tx."""
    assert FIX.get("tx_cbor"), "fixture missing tx_cbor"
    ctx = CreateLoanContext.from_fixture(FIX)
    comp = assemble_components(ctx)
    tx_hex = FIX["tx_cbor"]
    assert comp.create_loan_redeemer.to_cbor().hex() in tx_hex
    assert comp.oracle_redeemer.to_cbor().hex() in tx_hex
    assert comp.loan_datum.to_cbor().hex() in tx_hex


_SCRIPT_LANG = {
    "plutusV1": "plutus:v1",
    "plutusV2": "plutus:v2",
    "plutusV3": "plutus:v3",
}


def _additional_utxo(ctx: CreateLoanContext) -> list[dict]:
    entries = []
    for u in ctx.inputs + ctx.ref_inputs:
        if not u.out_ref:
            continue
        value: dict = {"ada": {"lovelace": u.lovelace}}
        for policy, name, qty in u.assets:
            value.setdefault(policy, {})[name] = qty
        out: dict = {"address": u.address, "value": value}
        if u.datum:
            out["datum"] = u.datum
        if u.ref_script:
            lang = _SCRIPT_LANG.get(u.ref_script_type or "", "plutus:v2")
            out["script"] = {"language": lang, "cbor": u.ref_script}
        entries.append(
            {"transaction": {"id": u.out_ref[0]}, "index": u.out_ref[1], **out}
        )
    return entries


@pytest.mark.skipif(
    not os.environ.get("OGMIOS_HOST") or not FIX.get("tx_cbor"),
    reason="needs OGMIOS_HOST and captured tx_cbor",
)
def test_captured_create_loan_evaluates_on_ogmios():
    from charli3_dendrite.lending.danogo.transactions.verify import evaluate_tx_cbor

    ctx = CreateLoanContext.from_fixture(FIX)
    try:
        result = evaluate_tx_cbor(FIX["tx_cbor"], _additional_utxo(ctx))
    except (requests.exceptions.RequestException, OSError) as exc:
        pytest.skip(f"ogmios unreachable: {exc}")
    assert result, "no redeemer budgets returned"
    for entry in result:
        assert entry.get("budget", {}).get("memory", 0) > 0
